def compute(vars):
    combined_ratio = vars["v1"]
    percentage = round(combined_ratio * 100, 2)

    return {
        "value": percentage,
        "trace": {
            "Combined Ratio": combined_ratio,
            "Percentage": percentage,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
